<?php
$id=(int)($_GET['id']??0);
$stmt=db()->prepare('SELECT * FROM applications WHERE id=?');
$stmt->execute([$id]);
$application=$stmt->fetch();
if(!$application){http_response_code(404);exit('Dossier introuvable.');}
$eventsStmt=db()->prepare('SELECT e.*, a.display_name FROM application_events e LEFT JOIN admins a ON a.id=e.admin_id WHERE e.application_id=? ORDER BY e.created_at DESC');
$eventsStmt->execute([$id]);$events=$eventsStmt->fetchAll();
$labels=status_labels();
$uses=json_decode((string)$application['funding_use'],true)?:[];
$fields=['birth_date'=>'Date de naissance','gender'=>'Sexe','nationality'=>'Nationalité','country'=>'Pays','region'=>'Région','city'=>'Ville','neighborhood'=>'Quartier','address'=>'Adresse','phone'=>'Téléphone','whatsapp'=>'WhatsApp','email'=>'E-mail','marital_status'=>'Situation matrimoniale','professional_status'=>'Situation professionnelle','education_level'=>'Niveau d’études','business_name'=>'Entreprise','business_start_date'=>'Création','business_sector'=>'Secteur de l’activité','business_location'=>'Localisation','employee_count'=>'Nombre d’employés','annual_revenue'=>'Chiffre d’affaires','registration_number'=>'Immatriculation','promoter_experience'=>'Expérience du promoteur','project_country'=>'Pays du projet','project_region'=>'Région du projet','project_city'=>'Ville du projet','project_location'=>'Localisation du projet','project_stage'=>'Stade','amount_requested'=>'Montant demandé','amount_approved'=>'Montant approuvé','currency'=>'Devise','personal_contribution'=>'Apport personnel','total_cost'=>'Coût total'];
